const {test}=require('node:test');const assert=require('node:assert/strict');
const load=()=>import('../tile-game-assets/bronze-age-world/tile-game/reactions.mjs');
test('only lifted residents panic; sustained lift and landing recover',async()=>{const {reaction,react,expression}=await load();const a=reaction(),b=reaction();react(a,true,.1);assert.equal(a.phase,'startled');for(let i=0;i<20;i++)react(a,true,.1);assert.equal(a.phase,'panic');assert.equal(a.intensity,1);assert.equal(expression(a).emoji,'😱');assert.equal(b.phase,'calm');react(a,false,.1);assert.equal(a.phase,'relief');for(let i=0;i<40;i++)react(a,false,.1);assert.equal(a.phase,'calm');assert.equal(a.intensity,0);assert.equal(expression(a).emoji,'');});
test('relifting during recovery restarts surprise; cancelled lift can recover',async()=>{const {reaction,react}=await load();const a=reaction();react(a,true,.1);react(a,false,.1);react(a,true,.1);assert.equal(a.phase,'startled');assert.equal(a.held,true);react(a,false,.1);for(let i=0;i<40;i++)react(a,false,.1);assert.equal(a.phase,'calm');});
